Path("apps/backend/prisma/migrations/20260818010000_add_student_cohort_progression/migration.sql").write_text('''-- Issue #301: authoritative programme cohort membership and progression history.\n-- These records are explicit institutional evidence; nothing is inferred from attendance/enrolment.\n\nCREATE TYPE "StudentCohortStatus" AS ENUM ('Planned', 'Active', 'Completed', 'Archived');\nCREATE TYPE "StudentCohortMembershipExitReason" AS ENUM ('Withdrawn', 'Transferred', 'Graduated', 'Other');\nCREATE TYPE "StudentProgressionStatus" AS ENUM ('Progressed', 'Retained', 'Withdrawn', 'Inactive', 'Graduated', 'Transferred');\n\nCREATE TABLE "StudentCohort" (\n  "id" TEXT NOT NULL,\n  "programmeId" TEXT NOT NULL,\n  "code" TEXT NOT NULL,\n  "name" TEXT NOT NULL,\n  "intakeYear" INTEGER NOT NULL,\n  "expectedGraduationYear" INTEGER NOT NULL,\n  "status" "StudentCohortStatus" NOT NULL DEFAULT 'Active',\n  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  "updatedAt" TIMESTAMP(3) NOT NULL,\n  CONSTRAINT "StudentCohort_pkey" PRIMARY KEY ("id"),\n  CONSTRAINT "StudentCohort_graduation_after_intake" CHECK ("expectedGraduationYear" >= "intakeYear")\n);\n\nCREATE TABLE "StudentCohortMembership" (\n  "id" TEXT NOT NULL,\n  "cohortId" TEXT NOT NULL,\n  "studentId" TEXT NOT NULL,\n  "joinedAt" DATE NOT NULL,\n  "exitedAt" DATE,\n  "exitReason" "StudentCohortMembershipExitReason",\n  "note" TEXT NOT NULL DEFAULT '',\n  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT "StudentCohortMembership_pkey" PRIMARY KEY ("id"),\n  CONSTRAINT "StudentCohortMembership_exit_after_join" CHECK ("exitedAt" IS NULL OR "exitedAt" >= "joinedAt"),\n  CONSTRAINT "StudentCohortMembership_exit_reason_consistent" CHECK (("exitedAt" IS NULL AND "exitReason" IS NULL) OR ("exitedAt" IS NOT NULL AND "exitReason" IS NOT NULL))\n);\n\nCREATE TABLE "StudentProgressionRecord" (\n  "id" TEXT NOT NULL,\n  "membershipId" TEXT NOT NULL,\n  "academicYear" TEXT NOT NULL,\n  "term" TEXT NOT NULL,\n  "periodStart" DATE NOT NULL,\n  "periodEnd" DATE NOT NULL,\n  "status" "StudentProgressionStatus" NOT NULL,\n  "note" TEXT NOT NULL DEFAULT '',\n  "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT "StudentProgressionRecord_pkey" PRIMARY KEY ("id"),\n  CONSTRAINT "StudentProgressionRecord_valid_period" CHECK ("periodEnd" >= "periodStart")\n);\n\nCREATE UNIQUE INDEX "StudentCohort_programmeId_code_key" ON "StudentCohort"("programmeId", "code");\nCREATE INDEX "StudentCohort_programmeId_intakeYear_status_idx" ON "StudentCohort"("programmeId", "intakeYear", "status");\nCREATE UNIQUE INDEX "StudentCohortMembership_cohortId_studentId_joinedAt_key" ON "StudentCohortMembership"("cohortId", "studentId", "joinedAt");\nCREATE INDEX "StudentCohortMembership_studentId_joinedAt_idx" ON "StudentCohortMembership"("studentId", "joinedAt");\nCREATE INDEX "StudentCohortMembership_cohortId_joinedAt_exitedAt_idx" ON "StudentCohortMembership"("cohortId", "joinedAt", "exitedAt");\nCREATE UNIQUE INDEX "StudentProgressionRecord_membershipId_academicYear_term_key" ON "StudentProgressionRecord"("membershipId", "academicYear", "term");\nCREATE INDEX "StudentProgressionRecord_membershipId_periodStart_idx" ON "StudentProgressionRecord"("membershipId", "periodStart");\nCREATE INDEX "StudentProgressionRecord_academicYear_term_status_idx" ON "StudentProgressionRecord"("academicYear", "term", "status");\n\nALTER TABLE "StudentCohort" ADD CONSTRAINT "StudentCohort_programmeId_fkey" FOREIGN KEY ("programmeId") REFERENCES "Programme"("id") ON DELETE RESTRICT ON UPDATE CASCADE;\nALTER TABLE "StudentCohortMembership" ADD CONSTRAINT "StudentCohortMembership_cohortId_fkey" FOREIGN KEY ("cohortId") REFERENCES "StudentCohort"("id") ON DELETE RESTRICT ON UPDATE CASCADE;\nALTER TABLE "StudentCohortMembership" ADD CONSTRAINT "StudentCohortMembership_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;\nALTER TABLE "StudentProgressionRecord" ADD CONSTRAINT "StudentProgressionRecord_membershipId_fkey" FOREIGN KEY ("membershipId") REFERENCES "StudentCohortMembership"("id") ON DELETE RESTRICT ON UPDATE CASCADE;\n\nCREATE OR REPLACE FUNCTION prevent_overlapping_student_cohort_memberships() RETURNS trigger AS $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM "StudentCohortMembership" existing\n    WHERE existing."studentId" = NEW."studentId"\n      AND existing.id <> NEW.id\n      AND daterange(existing."joinedAt", COALESCE(existing."exitedAt" + 1, 'infinity'::date), '[)')\n          && daterange(NEW."joinedAt", COALESCE(NEW."exitedAt" + 1, 'infinity'::date), '[)')\n  ) THEN\n    RAISE EXCEPTION 'Student cohort memberships cannot overlap';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\nCREATE TRIGGER "StudentCohortMembership_no_overlap" BEFORE INSERT OR UPDATE ON "StudentCohortMembership" FOR EACH ROW EXECUTE FUNCTION prevent_overlapping_student_cohort_memberships();\n\nCREATE OR REPLACE FUNCTION protect_student_cohort_membership_history() RETURNS trigger AS $$\nBEGIN\n  IF OLD."cohortId" <> NEW."cohortId" OR OLD."studentId" <> NEW."studentId" OR OLD."joinedAt" <> NEW."joinedAt" THEN\n    RAISE EXCEPTION 'Cohort membership identity is immutable';\n  END IF;\n  IF OLD."exitedAt" IS NOT NULL AND (NEW."exitedAt" IS DISTINCT FROM OLD."exitedAt" OR NEW."exitReason" IS DISTINCT FROM OLD."exitReason") THEN\n    RAISE EXCEPTION 'Closed cohort membership cannot be rewritten';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\nCREATE TRIGGER "StudentCohortMembership_history_guard" BEFORE UPDATE ON "StudentCohortMembership" FOR EACH ROW EXECUTE FUNCTION protect_student_cohort_membership_history();\n\nCREATE OR REPLACE FUNCTION validate_progression_membership_period() RETURNS trigger AS $$\nDECLARE m "StudentCohortMembership"%ROWTYPE;\nBEGIN\n  SELECT * INTO m FROM "StudentCohortMembership" WHERE id = NEW."membershipId";\n  IF NOT FOUND THEN RAISE EXCEPTION 'Cohort membership not found'; END IF;\n  IF NEW."periodStart" < m."joinedAt" OR (m."exitedAt" IS NOT NULL AND NEW."periodEnd" > m."exitedAt") THEN\n    RAISE EXCEPTION 'Progression period must fall within cohort membership dates';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\nCREATE TRIGGER "StudentProgressionRecord_membership_period" BEFORE INSERT ON "StudentProgressionRecord" FOR EACH ROW EXECUTE FUNCTION validate_progression_membership_period();\n\nCREATE OR REPLACE FUNCTION prevent_student_progression_rewrite() RETURNS trigger AS $$\nBEGIN\n  RAISE EXCEPTION 'Student progression history is append-only';\nEND;\n$$ LANGUAGE plpgsql;\nCREATE TRIGGER "StudentProgressionRecord_no_update" BEFORE UPDATE ON "StudentProgressionRecord" FOR EACH ROW EXECUTE FUNCTION prevent_student_progression_rewrite();\nCREATE TRIGGER "StudentProgressionRecord_no_delete" BEFORE DELETE ON "StudentProgressionRecord" FOR EACH ROW EXECUTE FUNCTION prevent_student_progression_rewrite();\n\nDO $$\nDECLARE table_name text; api_role text; tables constant text[] := ARRAY['StudentCohort','StudentCohortMembership','StudentProgressionRecord'];\nBEGIN\n  FOREACH table_name IN ARRAY tables LOOP\n    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);\n    EXECUTE format('REVOKE ALL PRIVILEGES ON TABLE public.%I FROM PUBLIC', table_name);\n  END LOOP;\n  FOR api_role IN SELECT rolname FROM pg_roles WHERE rolname = ANY (ARRAY['anon','authenticated','service_role']) LOOP\n    FOREACH table_name IN ARRAY tables LOOP\n      EXECUTE format('REVOKE ALL PRIVILEGES ON TABLE public.%I FROM %I', table_name, api_role);\n    END LOOP;\n  END LOOP;\nEND $$;\n''')

Path("packages/shared-types/src/student-progression.test.ts").write_text('''import { describe, expect, test } from "bun:test";\nimport { AppendStudentProgressionInput, CreateStudentCohortInput, ExitStudentCohortMembershipInput } from "./student-progression.ts";\n\ndescribe("student progression contracts", () => {\n  test("rejects expected graduation before intake", () => {\n    expect(CreateStudentCohortInput.safeParse({ programmeId: "dse", code: "2026", name: "2026", intakeYear: 2026, expectedGraduationYear: 2025 }).success).toBe(false);\n  });\n  test("accepts explicit progression lifecycle states", () => {\n    for (const status of ["Progressed", "Retained", "Withdrawn", "Inactive", "Graduated", "Transferred"]) {\n      expect(AppendStudentProgressionInput.safeParse({ membershipId: "00000000-0000-4000-8000-000000000001", academicYear: "2026-2027", term: "Semester 1", periodStart: "2026-09-01", periodEnd: "2027-01-31", status }).success).toBe(true);\n    }\n  });\n  test("requires dated exit reason and valid period ordering", () => {\n    expect(ExitStudentCohortMembershipInput.safeParse({ exitedAt: "2027-01-01", exitReason: "Transferred" }).success).toBe(true);\n    expect(AppendStudentProgressionInput.safeParse({ membershipId: "00000000-0000-4000-8000-000000000001", academicYear: "2026-2027", term: "Semester 1", periodStart: "2027-02-01", periodEnd: "2027-01-01", status: "Progressed" }).success).toBe(false);\n  });\n});\n''')

Path("apps/backend/src/plugins/students/cohort-progression-db.test.ts").write_text('''import { afterAll, beforeAll, describe, expect, test } from "bun:test";\nimport { PrismaClient } from "@prisma/client";\nimport { getQaEvidenceCandidates } from "../qa/evidence/service.ts";\n\nconst enabled = process.env.COHORT_PROGRESSION_DB_TESTS === "1";\nconst db = new PrismaClient();\nconst ids = { student: crypto.randomUUID(), cohort1: crypto.randomUUID(), cohort2: crypto.randomUUID(), membership1: crypto.randomUUID(), membership2: crypto.randomUUID() };\n\ndescribe.skipIf(!enabled)("cohort progression database integrity", () => {\n  beforeAll(async () => {\n    await db.student.create({ data: { id: ids.student, name: "Issue 301 Student", email: `issue301-${ids.student}@example.test`, studentId: `I301-${ids.student.slice(0, 8)}` } });\n    await db.studentCohort.create({ data: { id: ids.cohort1, programmeId: "dse", code: `I301-A-${ids.cohort1.slice(0, 6)}`, name: "Issue 301 cohort A", intakeYear: 2026, expectedGraduationYear: 2030 } });\n    await db.studentCohort.create({ data: { id: ids.cohort2, programmeId: "dse", code: `I301-B-${ids.cohort2.slice(0, 6)}`, name: "Issue 301 cohort B", intakeYear: 2027, expectedGraduationYear: 2031 } });\n  });\n  afterAll(async () => {\n    await db.studentProgressionRecord.deleteMany({ where: { membership: { studentId: ids.student } } }).catch(() => undefined);\n    await db.studentCohortMembership.deleteMany({ where: { studentId: ids.student } }).catch(() => undefined);\n    await db.studentCohort.deleteMany({ where: { id: { in: [ids.cohort1, ids.cohort2] } } }).catch(() => undefined);\n    await db.student.delete({ where: { id: ids.student } }).catch(() => undefined);\n    await db.$disconnect();\n  });\n\n  test("preserves multi-period history and supports transfer between non-overlapping cohorts", async () => {\n    await db.studentCohortMembership.create({ data: { id: ids.membership1, cohortId: ids.cohort1, studentId: ids.student, joinedAt: new Date("2026-09-01") } });\n    const first = await db.studentProgressionRecord.create({ data: { membershipId: ids.membership1, academicYear: "2026-2027", term: "Semester 1", periodStart: new Date("2026-09-01"), periodEnd: new Date("2027-01-31"), status: "Progressed" } });\n    await db.studentProgressionRecord.create({ data: { membershipId: ids.membership1, academicYear: "2026-2027", term: "Semester 2", periodStart: new Date("2027-02-01"), periodEnd: new Date("2027-06-30"), status: "Retained" } });\n    await db.studentCohortMembership.update({ where: { id: ids.membership1 }, data: { exitedAt: new Date("2027-06-30"), exitReason: "Transferred" } });\n    await db.studentCohortMembership.create({ data: { id: ids.membership2, cohortId: ids.cohort2, studentId: ids.student, joinedAt: new Date("2027-07-01") } });\n    expect(await db.studentProgressionRecord.count({ where: { membershipId: ids.membership1 } })).toBe(2);\n    expect((await db.studentProgressionRecord.findUniqueOrThrow({ where: { id: first.id } })).status).toBe("Progressed");\n  });\n\n  test("rejects overlapping membership and duplicate academic period", async () => {\n    await expect(db.studentCohortMembership.create({ data: { cohortId: ids.cohort1, studentId: ids.student, joinedAt: new Date("2027-05-01") } })).rejects.toThrow();\n    await expect(db.studentProgressionRecord.create({ data: { membershipId: ids.membership1, academicYear: "2026-2027", term: "Semester 1", periodStart: new Date("2026-09-01"), periodEnd: new Date("2027-01-31"), status: "Withdrawn" } })).rejects.toThrow();\n  });\n\n  test("rejects progression outside membership window and direct history rewrite", async () => {\n    await expect(db.studentProgressionRecord.create({ data: { membershipId: ids.membership2, academicYear: "2027-2028", term: "Semester 0", periodStart: new Date("2027-06-01"), periodEnd: new Date("2027-06-30"), status: "Transferred" } })).rejects.toThrow();\n    const row = await db.studentProgressionRecord.findFirstOrThrow({ where: { membershipId: ids.membership1 } });\n    await expect(db.studentProgressionRecord.update({ where: { id: row.id }, data: { status: "Graduated" } })).rejects.toThrow();\n    await expect(db.studentProgressionRecord.delete({ where: { id: row.id } })).rejects.toThrow();\n  });\n\n  test("QA retrieval exposes exact cohort/time scope and institutional provenance", async () => {\n    const membership = await getQaEvidenceCandidates("dse", "aun-qa-v4:8.1:research:c8-e01:evidence:1");\n    const membershipCandidate = membership.candidates.find((item) => item.attributes.studentId === ids.student);\n    expect(membershipCandidate?.scope?.cohortId).toBe(ids.cohort1);\n    expect(membershipCandidate?.provenance?.authority).toBe("officialInstitutionalRecord");\n\n    const progression = await getQaEvidenceCandidates("dse", "aun-qa-v4:8.1:research:c8-e01:evidence:2");\n    const rows = progression.candidates.filter((item) => item.attributes.studentId === ids.student);\n    expect(rows.length).toBe(2);\n    expect(rows[0]?.scope?.academicYear).toBe("2026-2027");\n    expect(rows[0]?.periodKey).toContain("2026-2027");\n    expect(rows[0]?.provenance?.authority).toBe("officialInstitutionalRecord");\n  });\n});\n''')

